    id: "hist-2026-hl-em-s1-q2a", topicId: "hist-em-irl-1", conceptId: "offer-similar-accounts-characteristics-people-gaelic",
    section: "1", questionRef: "2026 HL Early Modern Section 1 Q2(a)",
    stem: "Case study: The Plantation of Laois‐Offaly",
    questionText: "Do the documents offer similar accounts of the characteristics of the people of Gaelic Ireland? Give reasons for your answer, referring to the documents.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 10,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Both documents offer negative accounts of the people of Gaelic Ireland.", marks: null, contextNote: "Points should be supported by reference to both documents, e.g.," },
    { id: "r-2", kind: "point", verbatim: "Doc A states that the Gaelic Irish live like beasts, without knowledge of God or good manners.", marks: null },
    { id: "r-3", kind: "point", verbatim: "They are violent and lazy. They do not farm but steal crops and livestock from the English Pale.", marks: null },
    { id: "r-4", kind: "point", verbatim: "They are “rude, beastly, ignorant and unruly infidels”.", marks: null },
    { id: "r-5", kind: "point", verbatim: "Doc B states that the Gaelic Irish are wicked, proud and violent. They are barbarous people, given to murder, robbery and deceit.", marks: null },
    { id: "r-6", kind: "point", verbatim: "Both writers put forward plans to reform Irish society.", marks: null },
    ],
